Why This Is Asked
- Tests ability to design streaming, multi-format log processing with compression and nesting.
- Probes time-window handling, per-tenant aggregation, and memory-conscious streaming.
- Evaluates how to gracefully skip unreadable files without failing the pipeline.

Key Concepts
- POSIX shell pipelines and standard tools (tail, zcat, awk)
- Mixed log formats (text and JSON) parsing without external parsers
- Sliding window aggregation per tenant/service
- Deduplication by message content within a time bucket

Code Example
```bash
#!/usr/bin/env bash
# Skeleton illustration
tail -F /logs/tenant-*/service-*/{*.log,*.log.gz} 2>/dev/null | \
zcat -f 2>/dev/null | \
awk '
function parse_ts(line) {
    if (match(line, /^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}/)) {
        return substr(line, RSTART, 19)
    } else if (match(line, /"ts":[0-9]+/)) {
        return strftime("%Y-%m-%d %H:%M:%S", substr(line, RSTART+5, RLENGTH-5))
    }
    return ""
}
function parse_level(line) {
    if (match(line, /^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2} ([A-Z]+)/)) {
        return substr(line, RSTART, RLENGTH)
    } else if (match(line, /"lvl":"[A-Z]+"/)) {
        gsub(/"lvl":"/, "", line)
        gsub(/".*/, "", line)
        return line
    }
    return ""
}
function parse_msg(line) {
    if (match(line, /^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2} [A-Z]+: (.*)/)) {
        return substr(line, RSTART+RLENGTH, length(line))
    } else if (match(line, /"msg":"[^"]+"/)) {
        gsub(/"msg":"/, "", line)
        gsub(/".*/, "", line)
        return line
    }
    return ""
}
{
    ts = parse_ts($0)
    lvl = parse_level($0)
    msg = parse_msg($0)

    if (lvl == "ERROR" && ts != "") {
        key = FILENAME
        gsub(/\/logs\//, "", key)
        gsub(/\/events\.log.*/, "", key)

        if (!(key in error_counts)) {
            error_counts[key] = 0
        }
        error_counts[key]++

        if (!(msg in error_messages[key])) {
            error_messages[key][msg] = 0
        }
        error_messages[key][msg]++
    }
}
END {
    for (key in error_counts) {
        print "Tenant/Service: " key
        print "Total Errors: " error_counts[key]
        print "Top 3 Messages:"
        n = 0
        for (msg in error_messages[key]) {
            if (n++ >= 3) break
            print "  " error_messages[key][msg] "x: " msg
        }
        print ""
    }
}'
```

## Why This Is Asked
This tests practical Unix log processing skills including mixed format parsing, gzip archive handling, path-derived service context, and time-window filtering logic.

## Key Concepts
- Robust streaming parsing of two log formats (ISO timestamp and JSON)
- Time window filtering with epoch conversion
- Per-service aggregation and top-N result extraction
- Graceful handling of unreadable files and gzip archives

## Code Example
```bash
find /logs -name 'service-*/[0-9]*.log*' -type f 2>/dev/null | \
while IFS= read -r f; do \
  if [[ $f == *.gz ]]; then \
    zcat "$f" 2>/dev/null || continue; \
  else \
    cat "$f" 2>/dev/null || continue; \
  fi; \
done | awk '
BEGIN { 
  "date +%s" | getline now; 
  cutoff = now - 3600;
}
{
  # Parse ISO timestamp format
  if (match($0, /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}/)) {
    ts = substr($0, RSTART, RLENGTH);
    cmd = "date -d \"" ts "\" +%s";
    cmd | getline epoch;
    close(cmd);
    if (epoch >= cutoff && $2 == "ERROR:") {
      service = FILENAME;
      gsub(/.*\//, "", service);
      gsub(//.*/, "", service);
      msg = substr($0, index($0, "ERROR:") + 6);
      count[service "|" msg]++;
    }
  }
  # Parse JSON format
  else if ($0 ~ /^{/) {
    # Extract ts, lvl, msg from JSON
    if (match($0, /"ts"[[:space:]]*:[[:space:]]*"[^"]*"/)) {
      json_ts = substr($0, RSTART, RLENGTH);
      gsub(/.*"/, "", json_ts);
      gsub(/".*/, "", json_ts);
      cmd = "date -d \"" json_ts "\" +%s";
      cmd | getline epoch;
      close(cmd);
      if (epoch >= cutoff) {
        if (match($0, /"lvl"[[:space:]]*:[[:space:]]*"ERROR"/)) {
          if (match($0, /"msg"[[:space:]]*:[[:space:]]*"[^"]*"/)) {
            json_msg = substr($0, RSTART, RLENGTH);
            gsub(/.*"/, "", json_msg);
            gsub(/".*/, "", json_msg);
            service = FILENAME;
            gsub(/.*\//, "", service);
            gsub(//.*/, "", service);
            count[service "|" json_msg]++;
          }
        }
      }
    }
  }
}
END {
  # Aggregate counts by service and output top 5 per service
  for (key in count) {
    split(key, parts, "|");
    service = parts[1];
    msg = parts[2];
    service_count[service "|" msg] = count[key];
    services[service] = 1;
  }

  for (svc in services) {
    print "\n=== " svc " ===";
    n = 0;
    for (key in service_count) {
      split(key, parts, "|");
      if (parts[1] == svc) {
        messages[++n] = parts[2];
        values[n] = service_count[key];
      }
    }

    # Simple bubble sort for top 5
    for (i = 1; i <= n; i++) {
      for (j = i + 1; j <= n; j++) {
        if (values[j] > values[i]) {
          temp = values[i]; values[i] = values[j]; values[j] = temp;
          temp = messages[i]; messages[i] = messages[j]; messages[j] = temp;
        }
      }
    }

    for (i = 1; i <= (n < 5 ? n : 5); i++) {
      printf "%d: %s\n", values[i], messages[i];
    }
  }
}'
```

This solution handles mixed log formats, gzip archives, time-based filtering, per-service aggregation, and gracefully skips unreadable files.

## Why This Is Asked
This question evaluates the ability to handle mixed text and JSON logs, manage log rotation and compression, and perform cross-host aggregation with time-based filtering. It tests regex parsing, time-windowing, deduplication logic, and working within POSIX shell constraints without external dependencies.

## Key Concepts
- POSIX shell constraints with gzipped logs and mixed formats
- Time-window filtering for the last 30 minutes
- Robust user extraction from both plaintext and JSON logs
- Case-insensitive deduplication with per-host aggregation

## Code Example
```bash
for host in $(awk -F'[/=]' '/^\/(logs|var)\/log\// && !/^#/ {print $3}' /etc/hosts 2>/dev/null | sort -u); do
  users=$(find "/logs" -name '*.log*' -mmin -30 2>/dev/null | \
    xargs -I{} sh -c 'zcat -f "{}" 2>/dev/null' | \
    awk -v host="$host" '
      BEGIN {now=systime(); cutoff=now-1800}
      /^[[:space:]]/ {next}
      /^"?[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}/ {
        gsub(/[\[\]:]/, "", $1" "$2)
        cmd="date -d \""$1" "$2"\" +%s 2>/dev/null || date -d 0 +%s"
        cmd | getline ts; close(cmd)
        if (ts >= cutoff) {
          if ($0 ~ /ERROR|WARN/) {
            for (i=1; i<=NF; i++) {
              if ($i ~ /^user[=:]/) {
                gsub(/[,:"\047]/, "", $(i+1))
                print tolower($(i+1))
              }
            }
          }
        }
        next
      }
      /^"?\{/ {
        if (match($0, /"ts"[[:space:]]*:[[:space:]]*"([^"]+)"/, t)) {
          cmd="date -d \""t[1]"\" +%s 2>/dev/null || date -d 0 +%s"
          cmd | getline ts; close(cmd)
          if (ts >= cutoff && match($0, /"user"[[:space:]]*:[[:space:]]*"([^"]+)"/, u)) {
            print tolower(u[1])
          }
        }
        next
      }
    ' | sort -u | wc -l)
  echo "$host: $users unique users"
done
```

## Why This Is Asked
- Assesses ability to build robust, single-line data pipelines over multi-file logs, including compressed files, without external dependencies. 
- Tests time-window handling, cross-service aggregation, and per-tenant bucketing under rotation. 

## Key Concepts
- Stream processing with standard UNIX tools (find, xargs, zcat, awk). 
- JSON field extraction via regex in awk; resilient to line variations. 
- Time-window filtering using START/END derived from date; cross-file aggregation. 
- Sorting by computed metric (error rate) without extra tools.

## Code Example
```javascript
START=$(date -u -d "-6 hours" +"%Y-%m-%dT%H")
END=$(date -u +"%Y-%m-%dT%H")
find /var/log/cluster -type f \( -name '*.log' -o -name '*.log.gz' \) -print0 | \
  xargs -0 -I{} sh -lc 'case "{}" in *.gz) zcat "{}" ;; *) cat "{}" ;; esac' | \
  awk -v s="$START" -v e="$END" '{
    if (match($0, /"ts":"([^"]+)"/, a)) ts=a[1]; hour=substr(ts,1,13); gsub(/T/," ",hour); hour_key=hour;
    if (match($0, /"tenant":"([^"]+)"/, b)) tenant=b[1];
    if (match($0, /"lvl":"([^"]+)"/, c)) lvl=c[1];
    if (hour_key && tenant && hour_key>=s && hour_key<=e) {
      total[tenant] += 1; if (lvl=="ERROR") errors[tenant] += 1;
    }
  }
  END { for (t in total) { rate = total[t] ? errors[t] / total[t] : 0; printf "%s\t%.6f\n", t, rate } }
``` 

